using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Microsoft.Build.Logging.StructuredLogger;

var reader = new BinLogReader();
var records = new List<object>();

// Read the binlog
var build = BinaryLog.ReadBuild("build.binlog");

Console.WriteLine("=== BUILD RESULT ===");
Console.WriteLine($"Succeeded: {build.Succeeded}");
Console.WriteLine();

// Find all errors
Console.WriteLine("=== ALL ERRORS ===");
var errors = new List<(string project, string code, string message, string file, int line)>();
build.VisitAllChildren<Error>(error => {
    string project = "";
