int warnCount = 0;
build.VisitAllChildren<Warning>(warning => {
    if (warnCount++ < 30) {
        string project = "";
        var node = warning.Parent;
        while (node != null) {
            if (node is Project p) {
                project = p.Name;
                break;
            }
            node = node.Parent;
        }
        Console.WriteLine($"[{project}] {warning.Code}: {warning.Message}");
    }
});
