using System;
using Microsoft.Build.Logging.StructuredLogger;

var build = BinaryLog.ReadBuild("../build.binlog");

// List all projects and their references
Console.WriteLine("=== ALL PROJECTS IN BUILD ===");
build.VisitAllChildren<Project>(p => {
    Console.WriteLine($"  {p.Name} -> {p.ProjectFile}");
});

Console.WriteLine();
Console.WriteLine("=== PROJECT DEPENDENCIES (ProjectReference items) ===");
build.VisitAllChildren<AddItem>(item => {
    if (item.Name == "ProjectReference") {
        BaseNode node = item.Parent;
        string project = "";
        while (node != null) {
            if (node is Project p) { project = p.Name; break; }
            node = (node as TreeNode)?.Parent;
        }
        foreach (var child in item.Children) {
            Console.WriteLine($"  {project} references: {child}");
        }
    }
});

Console.WriteLine();
Console.WriteLine("=== PACKAGE REFERENCES ===");
build.VisitAllChildren<AddItem>(item => {
    if (item.Name == "PackageReference") {
        BaseNode node = item.Parent;
        string project = "";
        while (node != null) {
            if (node is Project p) { project = p.Name; break; }
            node = (node as TreeNode)?.Parent;
        }
        foreach (var child in item.Children) {
            Console.WriteLine($"  {project}: {child}");
        }
    }
});

// Show source file contents if embedded
Console.WriteLine();
