    if (p.Name != "Services.csproj") return;

    // Look at all Items
    p.VisitAllChildren<AddItem>(item => {
        if (item.Name == "PackageReference" || item.Name == "Reference" || item.Name == "ProjectReference") {
            Console.WriteLine($"  [{item.Name}]");
            foreach (var child in item.Children)
                Console.WriteLine($"    {child}");
        }
    });

    // Look at resolved references
    p.VisitAllChildren<NamedNode>(n => {
        if (n.Name != null && n.Name.Contains("Newtonsoft"))
            Console.WriteLine($"  Found Newtonsoft ref: {n.Name} ({n.GetType().Name})");
    });

    // Check the Target that failed
    p.VisitAllChildren<Target>(t => {
        bool hasErr = false;
        t.VisitAllChildren<Error>(e => hasErr = true);
        if (hasErr)
            Console.WriteLine($"  Failed target: {t.Name}");
    });
});

// Check what references Api has vs Services
Console.WriteLine();
Console.WriteLine("=== REFERENCE ASSEMBLIES FOR SERVICES ===");
build.VisitAllChildren<Project>(p => {
    if (p.Name != "Services.csproj") return;
    p.VisitAllChildren<AddItem>(item => {
        if (item.Name == "ReferencePath" || item.Name == "_ResolveAssemblyReferenceResolvedFiles") {
            foreach (var child in item.Children) {
                var text = child.ToString();
                if (text.Contains("Newtonsoft"))
                    Console.WriteLine($"  {text}");
            }
        }
    });
});

